node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ' columns:', cols.map(c => c.name).join(', '));
  const count = db.prepare('SELECT COUNT(*) as c FROM ' + t.name).get();
  console.log(t.name + ' rows:', count.c);
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get all airports (unique origins and destinations)
const airports = db.prepare(\"SELECT DISTINCT origin FROM flights WHERE source_skill='tau2Airline' UNION SELECT DISTINCT destination FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('Airports:', airports);

// Get all flights
const flights = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('\nAll flights (' + flights.length + '):');
flights.forEach(f => {
  console.log(f.flight_id, f.origin, '->', f.destination, '|', f.departure_time, '-', f.arrival_time, '| stops:', f.stops, '| status:', f.status, '| cabin_prices:', f.cabin_prices_json, '| dates:', f.dates_json);
});
"

