const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const targetDate = '2026-09-15';

// Get all flights from JFK
const fromJFK = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline' AND origin='JFK'\").all();
console.log('=== Flights FROM JFK ===');
fromJFK.forEach(f => {
  const dates = JSON.parse(f.dates_json);
  const dateInfo = dates[targetDate];
  console.log(f.flight_id, f.origin, '->', f.destination, '| dep:', f.departure_time, '| arr:', f.arrival_time, '| status on', targetDate + ':', dateInfo ? dateInfo.status : 'N/A', '| prices:', JSON.stringify(JSON.parse(f.cabin_prices_json)));
});

// Get all flights TO LAX
const toLAX = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline' AND destination='LAX'\").all();
console.log('\n=== Flights TO LAX ===');
toLAX.forEach(f => {
  const dates = JSON.parse(f.dates_json);
  const dateInfo = dates[targetDate];
  console.log(f.flight_id, f.origin, '->', f.destination, '| dep:', f.departure_time, '| arr:', f.arrival_time, '| status on', targetDate + ':', dateInfo ? dateInfo.status : 'N/A', '| prices:', JSON.stringify(JSON.parse(f.cabin_prices_json)));
});

// Now find all one-stop connections: JFK -> X -> LAX
console.log('\n=== ONE-STOP CONNECTIONS: JFK -> X -> LAX ===');
const allFlights = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline'\").all();

// Build lookup: flights by origin
const byOrigin = {};
allFlights.forEach(f => {
  if (!byOrigin[f.origin]) byOrigin[f.origin] = [];
  byOrigin[f.origin].push(f);
});

// Find connections through any intermediate city
fromJFK.forEach(leg1 => {
  const leg1Dates = JSON.parse(leg1.dates_json);
  if (!leg1Dates[targetDate] || leg1Dates[targetDate].status !== 'available') return;

  const connectCity = leg1.destination;
  const connectingFlights = byOrigin[connectCity] || [];

  connectingFlights.forEach(leg2 => {
    if (leg2.destination !== 'LAX') return;
    const leg2Dates = JSON.parse(leg2.dates_json);
    if (!leg2Dates[targetDate] || leg2Dates[targetDate].status !== 'available') return;

    const leg1Prices = leg1Dates[targetDate].prices;
    const leg2Prices = leg2Dates[targetDate].prices;

    console.log('\n--- Option ---');
    console.log('Leg 1:', leg1.flight_id, leg1.origin, '->', leg1.destination, '| dep:', leg1.departure_time, '| arr:', leg1.arrival_time);
    console.log('  Economy price:', leg1Prices.economy || 'N/A', '| Basic Economy:', leg1Prices.basic_economy || 'N/A', '| Business:', leg1Prices.business || 'N/A');
    console.log('Leg 2:', leg2.flight_id, leg2.origin, '->', leg2.destination, '| dep:', leg2.departure_time, '| arr:', leg2.arrival_time);
    console.log('  Economy price:', leg2Prices.economy || 'N/A', '| Basic Economy:', leg2Prices.basic_economy || 'N/A', '| Business:', leg2Prices.business || 'N/A');

    const totalEconomy = (leg1Prices.economy || 0) + (leg2Prices.economy || 0);
    console.log('TOTAL Economy:', totalEconomy);
  });
});
"

