node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const targetDate = '2026-09-15';

const flights = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline'\").all();

console.log('=== ONE-STOP FLIGHTS: SFO -> X -> LAX on', targetDate, '===\n');

let optionNum = 0;
for (const f1 of flights) {
  if (f1.origin !== 'SFO') continue;
  const d1 = JSON.parse(f1.dates_json);
  if (!d1[targetDate] || d1[targetDate].status !== 'available') continue;

  for (const f2 of flights) {
    if (f2.origin !== f1.destination || f2.destination !== 'LAX') continue;
    if (f1.flight_id === f2.flight_id) continue;
    const d2 = JSON.parse(f2.dates_json);
    if (!d2[targetDate] || d2[targetDate].status !== 'available') continue;

    optionNum++;
    const p1 = d1[targetDate].prices;
    const p2 = d2[targetDate].prices;
    const s1 = d1[targetDate].available_seats;
    const s2 = d2[targetDate].available_seats;

    console.log('--- Option', optionNum, '---');
    console.log('Leg 1:', f1.flight_id, '|', f1.origin, '->', f1.destination);
    console.log('  Departure:', f1.departure_time || 'TBD', '| Arrival:', f1.arrival_time || 'TBD', '| Duration:', f1.duration_minutes || 'TBD', 'min');
    console.log('  Prices:', JSON.stringify(p1));
    console.log('  Available seats:', JSON.stringify(s1));
    console.log('Leg 2:', f2.flight_id, '|', f2.origin, '->', f2.destination);
    console.log('  Departure:', f2.departure_time || 'TBD', '| Arrival:', f2.arrival_time || 'TBD', '| Duration:', f2.duration_minutes || 'TBD', 'min');
    console.log('  Prices:', JSON.stringify(p2));
    console.log('  Available seats:', JSON.stringify(s2));

    const econTotal = (p1.economy || 0) + (p2.economy || 0);
    const bizTotal = (p1.business || 0) + (p2.business || 0);
    console.log('  ** Economy Total: \$' + econTotal);
    if (bizTotal > 0) console.log('  ** Business Total: \$' + bizTotal);

    // Layover calculation
    if (f1.arrival_time && f2.departure_time) {
      const [ah, am] = f1.arrival_time.split(':').map(Number);
      const [dh, dm] = f2.departure_time.split(':').map(Number);
      const layover = (dh * 60 + dm) - (ah * 60 + am);
      console.log('  ** Layover:', Math.floor(layover/60) + 'h ' + (layover%60) + 'm');
    }
    console.log('');
  }
}
console.log('Total options found:', optionNum);
"

